def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        opp = history[1][1]
        if opp == 'D':
            return 'D'
        return 'C'
    opp_last = history[-1][1]
    my_last = history[-1][0]
    opp_prev = history[-2][1]
    if n < 10:
        if opp_last == 'D':
            return 'D'
        return 'C'
    def count_opp_defections(window):
        start = max(0, n - window)
        c = 0
        for i in range(start, n):
            if history[i][1] == 'D':
                c += 1
        return c
    def count_my_defections(window):
        start = max(0, n - window)
        c = 0
        for i in range(start, n):
            if history[i][0] == 'D':
                c += 1
        return c
    def last_opp_defection_index():
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                return i
        return -1
    def last_my_defection_index():
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D':
                return i
        return -1
    opp_def_10 = count_opp_defections(10)
    my_def_10 = count_my_defections(10)
    opp_def_20 = count_opp_defections(20)
    my_def_20 = count_my_defections(20)
    last_opp_def = last_opp_defection_index()
    last_my_def = last_my_defection_index()
    rounds_since_opp_def = n - 1 - last_opp_def if last_opp_def >= 0 else n
    rounds_since_my_def = n - 1 - last_my_def if last_my_def >= 0 else n
    if n >= 95:
        opp_total_def = count_opp_defections(n)
        if opp_total_def > n * 0.5:
            return 'D'
        if opp_total_def > n * 0.3:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'
    if opp_def_10 >= 8:
        return 'D'
    if opp_def_10 >= 6:
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.4:
            return 'D'
        return 'C'
    if opp_last == 'D' and my_last == 'D':
        if rounds_since_opp_def <= 1:
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'
    if opp_last == 'D' and my_last == 'C':
        if opp_prev == 'D':
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    if opp_last == 'C' and my_last == 'D':
        if rounds_since_my_def >= 3:
            return 'C'
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    if opp_def_20 >= 8:
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.25:
            return 'D'
        return 'C'
    if opp_def_20 <= 1 and my_def_20 <= 1:
        return 'C'
    if opp_def_20 >= 4:
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    if rng.random() < 0.03:
        return 'D'
    return 'C'

